requiredRule.cloudFirestoreSnippet:
match /databases/{database}/documents {
  // Server-owned: written and read only by Cloud Functions via the Admin SDK,
  // which is not subject to these rules. No client path may reach them.
  match /enterprise_outreach_drafts/{draftId}       { allow read, write: if false; }
  match /enterprise_outreach_receipts/{receiptId}   { allow read, write: if false; }
  match /enterprise_outreach_commands/{commandId}   { allow read, write: if false; }
  match /enterprise_legal_holds/{draftId}           { allow read, write: if false; }
  match /enterprise_jurisdiction_approvals/{code}   { allow read, write: if false; }
}
